import React, { useState, useEffect } from 'react';
import PropTypes from 'prop-types';
import './movie-list.scss';

import { SwiperSlide, Swiper } from 'swiper/react';
import tmdbApi, { category } from '../../api/tmdbApi';
import MovieCard from '../movie-card/MovieCard';

const MovieList = props => {
    const [items, setItems] = useState([]);

    useEffect(() => {
        const getList = async () => {
            // IF CUSTOM MOVIES ARE PASSED FROM HOME, USE THEM DIRECTLY!
            if (props.movies && props.movies.length > 0) {
                const enriched = await Promise.all(
                    props.movies.map(async (movie) => {
                        try {
                            const res = await tmdbApi.search(category.movie, {
                                params: { query: movie.title }
                            });
                            const match = res.results && res.results[0];
                            return {
                                ...movie,
                                id: match ? match.id : (movie.movieId || movie.id),
                                title: match ? (match.title || match.name) : movie.title,
                                poster_path: match ? match.poster_path : null,
                                backdrop_path: match ? match.backdrop_path : null,
                            };
                        } catch (err) {
                            // If a 404 or network error occurs for this title, fallback to raw movie data safely
                            return {
                                ...movie,
                                id: movie.movieId || movie.id,
                                poster_path: null,
                            };
                        }
                    })
                );
                setItems(enriched);
                return;
            }

            // Otherwise, fallback to original TMDB fetching behavior
            let response = null;
            const params = {};

            if (props.type !== 'all') {
                switch(props.category) {
                    case category.movie:
                        response = await tmdbApi.getMoviesList(props.type, {params});
                        break;
                    default:
                        response = await tmdbApi.getTvList(props.type, {params});
                }
            } else {
                response = await tmdbApi.similar(props.category, props.id);
            }
            setItems(response.results || []);
        }
        getList();
    }, [props.movies, props.category, props.type, props.id]);

    return (
        <div className="movie-list">
            <Swiper
                grabCursor={true}
                spaceBetween={10}
                slidesPerView={'auto'}
            >
                {
                    items.map((item, i) => (
                        <SwiperSlide key={i}>
                            <MovieCard category={props.category} item={item}/>
                        </SwiperSlide>
                    ))
                }
            </Swiper>
        </div>
    );
}

MovieList.propTypes = {
    category: PropTypes.string.isRequired,
    type: PropTypes.string.isRequired
}

export default MovieList;
